-- Nidio -- V33: corrige 11 fotos rotas de la galeria de V32 (3 fotos de la
-- V32 apuntaban a fotos que Pexels sirve como .png, pero la migracion las
-- linkeaba con extension .jpeg -- no cargaban). Se reemplazan por una foto
-- valida de la misma categoria y tipo. Tambien borra una publicacion de
-- prueba invalida (precio absurdo + foto de un plato, no es parte del
-- catalogo sembrado -- se creo a mano probando el flujo de Publicar).

UPDATE property_image SET url = 'https://images.pexels.com/photos/10973879/pexels-photo-10973879.jpeg?auto=compress&cs=tinysrgb&w=1200&h=800&fit=crop' WHERE url = 'https://images.pexels.com/photos/23916830/pexels-photo-23916830.jpeg?auto=compress&cs=tinysrgb&w=1200&h=800&fit=crop' AND property_id = (SELECT p.id FROM property p WHERE p.title = '2AMB C/ BALCON TERRAZA-FULL AMENITIES' AND p.address = 'AV AVELLANEDA 253, Comuna 6, Ciudad Autónoma de Buenos Aires');
