-- Publicacion de prueba invalida ("Departamento en venta en Flores", USD
-- 234.567.890, foto de un plato) -- no viene de las migraciones del
-- catalogo, se borra junto con sus fotos y favoritos (ON DELETE CASCADE).
DELETE FROM property WHERE title = 'Departamento en venta en Flores' AND price = 234567890;
